"use client";

import Image from "next/image";

interface HeroSectionProps {
  onBuyTicketClick?: () => void;
  onBuyMerchClick?: () => void;
}

export function HeroSection({ onBuyTicketClick, onBuyMerchClick }: HeroSectionProps) {
  const handleTicketClick = () => {
    if (onBuyTicketClick) {
      onBuyTicketClick();
    } else {
      const ticketSection = document.getElementById("tickets-section");
      ticketSection?.scrollIntoView({ behavior: "smooth" });
    }
  };

  const handleMerchClick = () => {
    if (onBuyMerchClick) {
      onBuyMerchClick();
    } else {
      const merchSection = document.getElementById("merch-section");
      merchSection?.scrollIntoView({ behavior: "smooth" });
    }
  };

  return (
    <section className="relative h-screen w-full overflow-hidden bg-black text-white font-sans select-none">
      
      {/* 1. BACKGROUND IMAGE LAYER */}
      <div className="absolute inset-0 z-0">
        <Image
          src="/images/bill-5.png"
          alt="Wakolosai Live Experience"
          fill
          className="object-cover object-center grayscale contrast-125"
          priority
          quality={100}
        />
        {/* Subtle Darkening Overlay */}
        <div className="absolute inset-0 bg-black/40" />
      </div>

      {/* 2. TOP RIGHT SUB-HEADER */}
      <div className="absolute top-6 right-6 md:top-10 md:right-12 z-20">
        <span className="text-[11px] md:text-xs font-black tracking-[0.25em] uppercase text-white">
          JOIN THE MOVEMENT
        </span>
      </div>

      {/* 3. MAIN HERO CONTENT GRID (Left Logo + Right Callout) */}
      <div className="relative z-10 h-full w-full max-w-7xl mx-auto px-6 md:px-12 flex items-center justify-between pointer-events-none">
        
        {/* LEFT SIDE: Wakolosai Branding Logo */}
        <div className="w-1/2 max-w-[280px] sm:max-w-[340px] md:max-w-[400px] pointer-events-auto">
  <Image
    src="/images/Wakolosai-logo.svg"
    alt="Wakolosai Logo"
    width={400}
    height={400}
    className="w-full h-auto object-contain drop-shadow-2xl"
    priority
  />
</div>

        {/* RIGHT SIDE: Punchy Client Hook */}
        <div className="w-1/2 text-right pointer-events-auto">
          <h2 className="text-2xl sm:text-4xl md:text-5xl lg:text-6xl font-serif italic leading-[1.1] uppercase tracking-tight leading-tight text-white drop-shadow-md">
            JE, WEWE NI <br />
            <span className="text-[#FFB800]">MKOLOOO?</span>
          </h2>
        </div>

      </div>

      {/* 4. BOTTOM DUAL ACTION BUTTONS (Clean & Modern Layout) */}
      <div className="absolute bottom-8 left-0 right-0 z-20 px-6 md:px-12 max-w-7xl mx-auto">
        <div className="flex items-center justify-between w-full">
          
          {/* Left CTA: Buy Ticket */}
          <button
            onClick={handleTicketClick}
            className="bg-[#FFB800] rounded-md rounded-lg hover:bg-[#e0a200] text-black font-extrabold text-sm md:text-base uppercase tracking-wider px-8 md:px-12 py-3 md:py-3.5 transition-colors duration-200"
          >
            Buy Ticket
          </button>

          {/* Right CTA: Buy Merch */}
          <button
            onClick={handleMerchClick}
            className="bg-[#FFB800] hover:bg-[#e0a200] text-black font-extrabold text-sm md:text-base uppercase tracking-wider px-8 md:px-12 py-3 md:py-3.5 rounded-md md:rounded-lg shadow-md hover:scale-105 active:scale-95 transition-all duration-200"
          >
            Buy merch
          </button>

        </div>
      </div>

    </section>
  );
}